if(s.input_instances){
const old=JSON.stringify(s.input_instances);
for(const v of Object.values(s.input_instances))for(const x of v)for(const u of x.uses)u.expected=fix(u.expected);
if(old!==JSON.stringify(s.input_instances))patches.push({op:"replace",path:`/steps/${i}/input_instances`,value:s.input_instances});
}}
a.conclusion_type=fix(a.conclusion_type);
patches.push({op:"replace",path:"/conclusion_type",value:a.conclusion_type});
